public class Mascota {
    String nombre;
    String especie;
    int edad;

    Mascota(String nombre, String especie, int edad) {
        this.nombre = nombre;
        this.especie = especie;
        this.edad = edad;
    }

    Mascota(String nombre) {
        this(nombre, "Unspecified", 0);
    }

    Mascota() {
        this("Unknown");
    }

    void mostrar() {
        System.out.println(nombre + " | " + especie + " | " + edad);
    }

    public static void main(String[] args) {
        Mascota m1 = new Mascota("Max", "Perro", 5);
        Mascota m2 = new Mascota("Luna");
        Mascota m3 = new Mascota();
        m1.mostrar();
        m2.mostrar();
        m3.mostrar();
    }
}

