public class CuentaBancaria {
    String titular;
    double saldo;

    CuentaBancaria(String titular, double saldo) {
        this.titular = titular;
        if (saldo < 0) {
            System.out.println("Error: balance cannot be negative. $0 used");
            this.saldo = 0;
        } else {
            this.saldo = saldo;
        }
    }

    CuentaBancaria(String titular) {
        this(titular, 0);
    }

    void mostrar() {
        System.out.println(titular + " | Balance: $" + saldo);
    }

    public static void main(String[] args) {
        CuentaBancaria c1 = new CuentaBancaria("María", 500);
        CuentaBancaria c2 = new CuentaBancaria("Carlos", -100);
        CuentaBancaria c3 = new CuentaBancaria("Ana");
        c1.mostrar();
        c2.mostrar();
        c3.mostrar();
    }
}

