public class Producto {
    String nombre;
    double precio;

    Producto(String nombre, double precio) {
        this.nombre = nombre;
        this.precio = precio;
    }

    void mostrar() {
        System.out.println(nombre + " - $" + precio);
    }
}

public class ProductoDigital extends Producto {
    int descargaMax;

    ProductoDigital(String nombre, double precio, int descargaMax) {
        super(nombre, precio);
        this.descargaMax = descargaMax;
    }
}

public class Main {
    public static void main(String[] args) {
        Producto p1 = new Producto("Laptop", 1200);
        ProductoDigital p2 = new ProductoDigital("Java Guide", 29.99, 1000);
        p1.mostrar();
        p2.mostrar();
        System.out.println("Max downloads: " + p2.descargaMax);
    }
}
